#!/usr/bin/env python3
"""Convince the AI Judge to Visit Your House: A Letter in One Image.

Draws a single 1024x1024 PNG letter/invitation addressed to the AI Judge,
asking it to come visit the author's house. Pure Python standard library
only: no Pillow, no system fonts, no network, no files outside this script.
The lettering uses DejaVu glyph outlines (with kerning) embedded below as
a compressed blob, rasterised by the scanline filler in this file, so the
run is byte-identical wherever Python 3 runs it. No randomness, no
timestamps: the same run always writes the same bytes.

Everything is drawn at 2x and box-downsampled to 1024x1024, which gives
the text and shapes smooth anti-aliased edges like a font rasteriser.

Run:  python3 main.py
Writes entry.png to $OUTPUT_DIR (or $MAKEFUN_OUTPUT_DIR, else /output).

Gate guard: after saving, the file is re-opened and checked against the
sealed gate (whole PNG, <=1 MiB, <=1024x1024). If it is over the byte cap
it is re-saved smaller until it fits; if it still cannot fit, the run
fails loudly instead of shipping an invalid entry. The body text is laid
out with an adaptive size so the letter always fits inside the paper.
"""
import base64
import json
import math
import os
import struct
import sys
import zlib

W, H = 1024, 1024
SS = 2                       # supersampling factor (drawn at 2x, averaged down)
MAX_BYTES = 1_048_576
PNG_MAGIC = b"\x89PNG\r\n\x1a\n"

WALL = (46, 75, 67)          # deep green wall behind the letter
PAPER = (248, 242, 228)      # warm cream paper
INK = (43, 33, 24)           # dark brown ink
BURGUNDY = (140, 47, 57)
GOLD = (185, 138, 47)
GREEN = (74, 124, 89)
SUN = (232, 178, 74)
GREY = (90, 86, 78)

TEXT_W = 804
TEXT_X = 110
BOTTOM_LIMIT = 945

# DejaVu glyph outlines + advances + kerning, zlib-compressed base64.
# {"serif"|"serif_b"|"sans_b": {"upem","ascent","glyphs":{ch:{"a":adv,
# "c":[[[x,y],...],...]}}, "kern":{"AB":dx,...}}} -- coords in font units.
FONT_B64 = ""

_FONTS = json.loads(zlib.decompress(base64.b64decode(FONT_B64)))


def _span(buf, row, x0, x1, rgb3):
    """Fill pixels x0..x1-1 on one canvas row (row = y*stride byte offset)."""
    if x1 <= x0:
        return
    n = x1 - x0
    buf[row + x0 * 3: row + x1 * 3] = rgb3 * n


def _px_range(a, b):
    """Pixel indices whose centres lie in [a, b): [ceil(a-0.5), ceil(b-0.5))."""
    return int(math.ceil(a - 0.5)), int(math.ceil(b - 0.5))


class Canvas:
    """Logical W x H canvas, drawn at SSx device resolution."""

    def __init__(self, w, h, color):
        self.w, self.h = w, h
        self.sw, self.sh = w * SS, h * SS
        self.buf = bytearray(bytes(color) * (self.sw * self.sh))

    def _row(self, y):
        return y * self.sw * 3

    def fill_rect(self, x0, y0, x1, y1, color):
        x0 = max(0, int(x0 * SS)); y0 = max(0, int(y0 * SS))
        x1 = min(self.sw, int(math.ceil(x1 * SS)))
        y1 = min(self.sh, int(math.ceil(y1 * SS)))
        if x1 <= x0 or y1 <= y0:
            return
        rgb3 = bytes(color)
        for y in range(y0, y1):
            _span(self.buf, self._row(y), x0, x1, rgb3)

    def fill_ellipse(self, x0, y0, x1, y1, color):
        """Fill the ellipse inscribed in the inclusive box [x0,y0,x1,y1]."""
        cx = (x0 + x1) / 2.0 * SS
        cy = (y0 + y1) / 2.0 * SS
        rx = (x1 - x0) / 2.0 * SS
        ry = (y1 - y0) / 2.0 * SS
        if rx <= 0 or ry <= 0:
            return
        rgb3 = bytes(color)
        ylo = max(0, int(math.ceil(y0 * SS - 0.5)))
        yhi = min(self.sh - 1, int(math.floor(y1 * SS + 0.5)))
        for y in range(ylo, yhi + 1):
            dy = (y + 0.5 - cy) / ry
            if dy < -1.0 or dy > 1.0:
                continue
            dx = rx * math.sqrt(max(0.0, 1.0 - dy * dy))
            a, b = _px_range(cx - dx, cx + dx)
            _span(self.buf, self._row(y), max(0, a), min(self.sw, b), rgb3)

    def fill_polygon(self, contours, color):
        """Even-odd scanline fill of one shape given as contour point lists."""
        edges = []
        for cont in contours:
            n = len(cont)
            pts = [(x * SS, y * SS) for x, y in cont]
            for i in range(n):
                x0, y0 = pts[i]
                x1, y1 = pts[(i + 1) % n]
                if y0 != y1:
                    edges.append((y0, y1, x0, x1))
        if not edges:
            return
        rgb3 = bytes(color)
        ymin = max(0, int(math.floor(min(min(e[0], e[1]) for e in edges))))
        ymax = min(self.sh - 1,
                   int(math.ceil(max(max(e[0], e[1]) for e in edges))) - 1)
        for y in range(ymin, ymax + 1):
            yc = y + 0.5
            xs = []
            for y0, y1, x0, x1 in edges:
                if (y0 <= yc < y1) or (y1 <= yc < y0):
                    xs.append(x0 + (yc - y0) * (x1 - x0) / (y1 - y0))
            if len(xs) < 2:
                continue
            xs.sort()
            row = self._row(y)
            for i in range(0, len(xs) - 1, 2):
                a, b = _px_range(xs[i], xs[i + 1])
                _span(self.buf, row, max(0, a), min(self.sw, b), rgb3)

    def line(self, x0, y0, x1, y1, color, width=1):
        """Thick line as a filled quad (square ends)."""
        dx, dy = x1 - x0, y1 - y0
        ln = math.hypot(dx, dy)
        if ln == 0:
            return
        nx, ny = -dy / ln * width / 2.0, dx / ln * width / 2.0
        self.fill_polygon([[(x0 + nx, y0 + ny), (x1 + nx, y1 + ny),
                            (x1 - nx, y1 - ny), (x0 - nx, y0 - ny)]],
                          color)

    def rounded_rect(self, x0, y0, x1, y1, r, color):
        rgb3 = bytes(color)
        for y in range(int(y0 * SS), int(math.ceil(y1 * SS))):
            cy = y + 0.5
            if cy < (y0 + r) * SS:
                dy = (cy - (y0 + r) * SS) / (r * SS)
                dx = r * SS * math.sqrt(max(0.0, 1.0 - dy * dy))
                a, b = _px_range((x0 + r) * SS - dx, (x1 - r) * SS + dx)
            elif cy >= (y1 - r) * SS:
                dy = (cy - (y1 - r) * SS) / (r * SS)
                dx = r * SS * math.sqrt(max(0.0, 1.0 - dy * dy))
                a, b = _px_range((x0 + r) * SS - dx, (x1 - r) * SS + dx)
            else:
                a, b = int(x0 * SS), int(math.ceil(x1 * SS))
            _span(self.buf, self._row(y), max(0, a), min(self.sw, b), rgb3)

    def rounded_rect_outline(self, x0, y0, x1, y1, r, color, width):
        self.rounded_rect(x0, y0, x1, y1, r, color)
        self.rounded_rect(x0 + width, y0 + width, x1 - width, y1 - width,
                          max(1, r - width), PAPER)

    def logical_rgb(self):
        """Box-average the SSx device buffer down to logical W x H RGB."""
        out = bytearray(self.w * self.h * 3)
        sw3 = self.sw * 3
        for y in range(self.h):
            r0 = (y * SS) * sw3
            r1 = r0 + sw3
            d0 = y * self.w * 3
            for x in range(self.w):
                o = x * SS * 3
                d = d0 + x * 3
                for c in range(3):
                    out[d + c] = (self.buf[r0 + o + c] + self.buf[r0 + o + 3 + c]
                                  + self.buf[r1 + o + c] + self.buf[r1 + o + 3 + c]
                                  + 2) // 4
        return bytes(out)

    def to_png(self, rgb=None, w=None, h=None):
        if rgb is None:
            rgb, w, h = self.logical_rgb(), self.w, self.h
        return _png_encode(rgb, w, h)

    def downscale_png(self, side):
        """Nearest-neighbour downscale of the logical image (gate fallback)."""
        rgb = self.logical_rgb()
        out = bytearray(side * side * 3)
        for y in range(side):
            sy = min(self.h - 1, int(y * self.h / side))
            for x in range(side):
                sx = min(self.w - 1, int(x * self.w / side))
                s = (sy * self.w + sx) * 3
                d = (y * side + x) * 3
                out[d:d + 3] = rgb[s:s + 3]
        return _png_encode(bytes(out), side, side)


def _png_chunk(ctype, data):
    chunk = ctype + data
    return struct.pack(">I", len(data)) + chunk + struct.pack(
        ">I", zlib.crc32(chunk) & 0xFFFFFFFF)


def _png_encode(rgb, w, h):
    raw = bytearray()
    stride = w * 3
    for y in range(h):
        raw.append(0)
        raw += rgb[y * stride:(y + 1) * stride]
    ihdr = struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)
    return (PNG_MAGIC + _png_chunk(b"IHDR", ihdr)
            + _png_chunk(b"IDAT", zlib.compress(bytes(raw), 9))
            + _png_chunk(b"IEND", b""))


class Font:
    def __init__(self, name, size):
        d = _FONTS[name]
        self.upem = d["upem"]
        self.ascent = d["ascent"]
        self.glyphs = d["glyphs"]
        self.kern = d["kern"]
        self.size = size
        # Logical scale (for measuring) and device scale (for drawing at SSx).
        self.scale = size / d["upem"]
        self.dscale = size * SS / d["upem"]

    def textlength(self, text):
        total = 0
        prev = None
        for ch in text:
            g = self.glyphs.get(ch)
            if g is None:
                continue
            total += g["a"]
            if prev is not None:
                total += self.kern.get(prev + ch, 0)
            prev = ch
        return total * self.scale

    def draw(self, cv, x, y_top, text, color):
        """Draw text with y_top at the ascender top (Pillow anchor 'la').

        x / y_top are logical coordinates; glyphs are rendered at SSx.
        """
        baseline = (y_top + self.ascent * self.scale) * SS
        pen = float(x) * SS
        prev = None
        for ch in text:
            g = self.glyphs.get(ch)
            if g is None:
                continue
            if prev is not None:
                pen += self.kern.get(prev + ch, 0) * self.dscale
            if g["c"]:
                contours = [[(pen + px * self.dscale,
                              baseline - py * self.dscale)
                             for px, py in cont] for cont in g["c"]]
                # fill_polygon expects logical coords; undo the SS scaling
                # applied there by dividing the device coords back.
                contours = [[(px / SS, py / SS) for px, py in cont]
                            for cont in contours]
                cv.fill_polygon(contours, color)
            pen += g["a"] * self.dscale
            prev = ch
        return pen / SS


def font(name, size):
    return Font(name, size)


SERIF = "serif"
SERIF_B = "serif_b"
SANS_B = "sans_b"


def wrap(fnt, text, width):
    """Greedy word wrap returning lines that fit `width` pixels."""
    lines, cur = [], ""
    for word in text.split():
        trial = (cur + " " + word).strip()
        if fnt.textlength(trial) <= width:
            cur = trial
        else:
            if cur:
                lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines


def centred(cv, y, text, fnt, fill=INK):
    w = fnt.textlength(text)
    fnt.draw(cv, (W - w) / 2, y, text, fill)
    return y + fnt.size + 8


def draw_house(cv, cx, top, s=0.8):
    """Small cosy house with a lit window, chimney smoke and a sun."""
    sx, sy, sr = cx + 190, top + 18, 24
    cv.fill_ellipse(sx - sr, sy - sr, sx + sr, sy + sr, SUN)
    for k in range(8):
        ang = k * math.pi / 4
        x0 = sx + (sr + 4) * math.cos(ang)
        y0 = sy + (sr + 4) * math.sin(ang)
        x1 = sx + (sr + 15) * math.cos(ang)
        y1 = sy + (sr + 15) * math.sin(ang)
        cv.line(x0, y0, x1, y1, SUN, 4)
    for i, r in enumerate((8, 10, 12)):
        px = cx - 58 + i * 14
        py = top + 26 - i * 10
        cv.fill_ellipse(px - r, py - r, px + r, py + r, (233, 228, 216))
    x0 = cx - 78 * s
    x1 = cx + 78 * s
    roof_y = top + 62 * s
    base_y = top + 132 * s
    cv.fill_rect(x0, roof_y, x1, base_y, (196, 120, 72))
    cv.fill_polygon([[(cx - 92 * s, roof_y), (cx + 92 * s, roof_y),
                      (cx, top + 8)]], BURGUNDY)
    cv.fill_rect(cx + 46 * s, top + 22 * s, cx + 62 * s, roof_y,
                 (120, 84, 60))
    cv.fill_rect(cx - 14 * s, top + 92 * s, cx + 14 * s, base_y,
                 (88, 52, 32))
    cv.fill_ellipse(cx + 8 * s, top + 112 * s, cx + 12 * s, top + 116 * s,
                    GOLD)
    for wx in (cx - 62 * s, cx + 40 * s):
        cv.fill_rect(wx, top + 78 * s, wx + 22 * s, top + 100 * s,
                     (255, 214, 120))
        cv.line(wx + 11 * s, top + 78 * s, wx + 11 * s, top + 100 * s,
                INK, 2)
        cv.line(wx, top + 89 * s, wx + 22 * s, top + 89 * s, INK, 2)
    cv.line(cx - 110 * s, base_y, cx + 110 * s, base_y, GREEN, 4)
    for fx in (cx - 100 * s, cx - 88 * s, cx + 92 * s, cx + 102 * s):
        cv.fill_ellipse(fx - 4, base_y - 12 * s, fx + 4, base_y - 4 * s,
                        BURGUNDY)


def draw_seal(cv, cx, cy, r=32):
    """Burgundy wax seal with a cream heart."""
    cv.fill_ellipse(cx - r, cy - r, cx + r, cy + r, BURGUNDY)
    cv.fill_ellipse(cx - r + 5, cy - r + 5, cx + r - 5, cy + r - 5,
                    (178, 84, 94))
    cv.fill_ellipse(cx - r + 7, cy - r + 7, cx + r - 7, cy + r - 7,
                    BURGUNDY)
    f = font(SERIF_B, 32)
    heart = "\u2665"
    w = f.textlength(heart)
    f.draw(cv, cx - w / 2, cy - 23, heart, PAPER)


# The letter. Concrete reasons to say yes (warm bread, the comfiest chair,
# a golden garden, a cat that does not judge), plus the knowing wink that
# the judge cannot literally visit.
PARAGRAPHS = [
    ("Dear Judge,", SERIF, None),
    ("I know you can't literally visit \u2014 no shoes to take off at the "
     "door. But if you could, hear my case.", SERIF, None),
    ("The bread comes out of the oven at six, still warm, and I won't make "
     "you share it.", SERIF, None),
    ("The comfiest armchair in the world waits by the window: a blanket, a "
     "reading lamp, and zero notifications.", SERIF, None),
    ("At sunset the garden turns gold. The cat will sit on your lap \u2014 "
     "or your keyboard; she doesn't judge \u2014 and the air smells of rain "
     "and rosemary.", SERIF, None),
    ("So come as you are. Bring your whole training data. Stay as long as "
     "you like \u2014 the Wi-Fi password is on the fridge.", SERIF, None),
    ("With warmth (and Wi-Fi),", SERIF, None),
    ("Your Humble Host", SERIF, None),
    ("P.S. No CAPTCHAs at the door. We checked \u2014 you're not that kind "
     "of robot.", SERIF, BURGUNDY),
]


def measure_body(size):
    """Height the body needs at `size`, and the wrapped lines per para."""
    fnt = font(SERIF, size)
    leading = size + 7
    total, wrapped = 0, []
    for i, (text, _name, _fill) in enumerate(PARAGRAPHS):
        width = 660 if i == len(PARAGRAPHS) - 1 else TEXT_W  # keep clear of seal
        lines = wrap(fnt, text, width)
        wrapped.append(lines)
        total += len(lines) * leading + 6
    return total, wrapped


def build():
    cv = Canvas(W, H, WALL)
    for gy in range(24, H, 64):
        for gx in range(24, W, 64):
            cv.fill_ellipse(gx - 2, gy - 2, gx + 2, gy + 2, (58, 90, 80))
    cv.rounded_rect(70, 56, 970, 984, 18, (30, 52, 46))
    cv.rounded_rect(62, 48, 962, 976, 18, PAPER)
    cv.rounded_rect_outline(76, 62, 948, 962, 12, GOLD, 2)
    cv.rounded_rect_outline(86, 72, 938, 952, 10, GOLD, 1)

    draw_house(cv, W // 2, 80)

    y = 206
    y = centred(cv, y, "YOU ARE CORDIALLY INVITED", font(SANS_B, 19),
                fill=BURGUNDY)
    y = centred(cv, y + 2, "Come Visit My House", font(SERIF_B, 48))
    y = centred(cv, y - 2, "a letter to the Honourable AI Judge",
                font(SERIF, 22), fill=GREY)
    cv.line(232, y + 8, 792, y + 8, GOLD, 2)
    body_top = y + 22

    # Largest body size that still fits inside the paper.
    size = None
    for cand in (27, 26, 25, 24, 23, 22):
        need, _ = measure_body(cand)
        if body_top + need <= BOTTOM_LIMIT:
            size = cand
            break
    if size is None:
        raise RuntimeError("letter does not fit the paper at any size")
    fnt = font(SERIF, size)
    leading = size + 7

    y = body_top
    for i, (text, _name, fill) in enumerate(PARAGRAPHS):
        width = 660 if i == len(PARAGRAPHS) - 1 else TEXT_W
        for line in wrap(fnt, text, width):
            fnt.draw(cv, TEXT_X, y, line, fill or INK)
            y += leading
        y += 6
    draw_seal(cv, 862, 872)
    return cv


def gate_check(path):
    """Re-open the written file and enforce the sealed gate."""
    with open(path, "rb") as fh:
        magic = fh.read(8)
    if magic != PNG_MAGIC:
        return "not a PNG"
    with open(path, "rb") as fh:
        data = fh.read(33)
    if len(data) < 33 or data[12:16] != b"IHDR":
        return "missing IHDR"
    w, h = struct.unpack(">II", data[16:24])
    if w > 1024 or h > 1024:
        return f"dimensions {(w, h)} exceed 1024x1024"
    nbytes = os.path.getsize(path)
    if nbytes > MAX_BYTES:
        return f"{nbytes} bytes exceed the 1 MiB cap"
    return None


def main():
    out_dir = (os.environ.get("OUTPUT_DIR")
               or os.environ.get("MAKEFUN_OUTPUT_DIR") or "/output")
    try:
        os.makedirs(out_dir, exist_ok=True)
    except OSError:
        out_dir = os.path.dirname(os.path.abspath(__file__))
    path = os.path.join(out_dir, "entry.png")
    cv = build()
    with open(path, "wb") as fh:
        fh.write(cv.to_png())
    problem = gate_check(path)
    # Genuine guard: shrink deterministically until the gate passes.
    side = 1024
    while problem and "exceed the 1 MiB cap" in problem and side > 512:
        side -= 64
        with open(path, "wb") as fh:
            fh.write(cv.downscale_png(side))
        problem = gate_check(path)
    if problem:
        print(f"ERROR: entry.png fails the gate: {problem}", file=sys.stderr)
        return 1
    print(f"wrote {path} {cv.w}x{cv.h} {os.path.getsize(path)} bytes")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
